.context-menu {
  user-select: none;
  list-style: none;
  margin: 0;
  padding: 0;
  min-width: 127px;
  width: auto;
  z-index: 10;
  box-sizing: border-box;
  background-color: #010a13;
  box-shadow: 0 0 1px #000, 0 0 1px #000;
  -webkit-user-select: none;
/* if the width is changed, also change moveNearBoundingRect in popout-window.js to account for border size in the
   alignment of subcontext menus */
  border-width: 2px;
  border-style: solid;
  border-image: linear-gradient(to bottom, #463714, #785a28) 1;
}
.context-menu:focus {
  outline: none;
}
