lol-uikit-comet-border.css:
:host {
  --border-color: transparent;
  --border-width: 2px;
  --comet-color: #f0e6d2;
  --comet-length: 100px;
  border: var(--border-width) solid var(--border-color);
  box-sizing: border-box;
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  pointer-events: none;
}
#glow {
  --animation-name: none;
  --height: 0;
  --width: 0;
  height: 100%;
  -webkit-filter: drop-shadow(0 0 1px var(--comet-color)) drop-shadow(0 0 1px var(--comet-color));
}
#top,
#bottom,
#left,
#right {
  overflow: hidden;
  position: absolute;
}
#top,
#bottom {
  height: var(--border-width);
  width: calc(100% + var(--border-width));
}
#top {
  left: calc(var(--border-width) * -1);
  top: calc(var(--border-width) * -1);
}
#bottom {
  bottom: calc(var(--border-width) * -1);
  transform: rotate(180deg);
}
#left,
#right {
  height: var(--border-width);
  width: calc(var(--height) - var(--border-width));
}
#left {
  right: calc(100% + var(--border-width) * 1);
  transform: rotate(270deg);
  transform-origin: 100% 0;
}
#right {
  left: 100%;
  top: calc(0% + var(--border-width) * -2);
  transform: rotate(90deg);
  transform-origin: 0 100%;
}
#left-comet,
#right-comet,
#top-comet,
#bottom-comet {
  animation-duration: 3s;
  animation-iteration-count: infinite;
  animation-name: var(--animation-name);
  animation-timing-function: linear;
  background-image: repeating-linear-gradient(270deg, transparent 0, var(--comet-color) 2px, transparent var(--comet-length), transparent calc(var(--width) + var(--height) - var(--border-width) * 2));
  height: 100%;
  position: absolute;
  width: calc(var(--width) + var(--height) + var(--comet-length));
}
#left-comet,
#right-comet {
  right: 0;
}
#top-comet,
#bottom-comet {
  left: calc(var(--comet-length) * -1);
}
@-moz-keyframes animate-comet {
  0% {
    transform: translateX(0px);
  }
  100% {
    transform: translateX(calc(var(--height) + var(--width) - var(--border-width) * 2));
  }
}
@-webkit-keyframes animate-comet {
  0% {
    transform: translateX(0px);
  }
  100% {
    transform: translateX(calc(var(--height) + var(--width) - var(--border-width) * 2));
  }
}
@-o-keyframes animate-comet {
  0% {
    transform: translateX(0px);
  }
  100% {
    transform: translateX(calc(var(--height) + var(--width) - var(--border-width) * 2));
  }
}
@keyframes animate-comet {
  0% {
    transform: translateX(0px);
  }
  100% {
    transform: translateX(calc(var(--height) + var(--width) - var(--border-width) * 2));
  }
}

